package io.floci.aws.services.eventbridgev2;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.floci.aws.core.common.AwsException;
import io.floci.aws.core.common.RequestConstraintCheck;
import io.floci.aws.core.common.SmithyValidationErrors;

import java.util.List;

/**
 * Checks EventBridge V2 event source requests against the constraints generated by
 * {@code tools/aws/regen_eventbridgev2_shapes.py}. The first ten violations are answered together as
 * {@code InvalidInputException}, in the wording AWS uses. A member of the wrong type is answered as
 * {@code SerializationException} with no message.
 */
final class EventBridgeV2RequestShapes {

    private static final int MAX_VIOLATIONS = 10;

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/eventbridgev2-request-shapes.json", "EventBridge V2 request shapes", new Messages(),
            new RequestConstraintCheck.ViolationOrder(false, true));

    private EventBridgeV2RequestShapes() {
    }

    /** {@code value} without the members that {@code shapeName} does not declare. */
    static JsonNode modeled(String shapeName, JsonNode value) {
        return CHECK.modeled(shapeName, value);
    }

    static void check(String operation, JsonNode request) {
        List<String> violations = CHECK.violations(operation, withoutWhsecPrefix(request));
        if (!violations.isEmpty()) {
            throw SmithyValidationErrors.exception("InvalidInputException",
                    violations.subList(0, Math.min(violations.size(), MAX_VIOLATIONS)));
        }
    }

    /** Only {@code violations} is used, and it reaches nothing but the type message. */
    private static final class Messages implements RequestConstraintCheck.Messages {
        private final RequestConstraintCheck.Messages standard =
                RequestConstraintCheck.standardMessages("InvalidInputException");

        @Override
        public AwsException type(String path, String type) {
            return new AwsException("SerializationException", null, 400);
        }

        @Override
        public AwsException bounds(String path, String type, Long min, Long max, Number size) {
            return standard.bounds(path, type, min, max, size);
        }

        @Override
        public AwsException pattern(String path, String pattern) {
            return standard.pattern(path, pattern);
        }

        @Override
        public AwsException enumValue(String path, List<String> values) {
            return standard.enumValue(path, values);
        }

        @Override
        public AwsException required(String path) {
            return standard.required(path);
        }
    }

    /** AWS judges the length of a Base64 HMAC secret without its {@code whsec_} prefix. */
    private static JsonNode withoutWhsecPrefix(JsonNode request) {
        JsonNode hmac = request.path("Configuration").path(WebhookEventsConfigurations.WEBHOOK)
                .path("AuthConfiguration").path(WebhookEventsConfigurations.HMAC);
        String secret = WebhookEventsConfigurations.hmacSecretValue(hmac);
        if (secret == null || secret.equals(hmac.path("SecretValue").textValue())) {
            return request;
        }
        ObjectNode copy = request.deepCopy();
        ((ObjectNode) copy.path("Configuration").path(WebhookEventsConfigurations.WEBHOOK)
                .path("AuthConfiguration").path(WebhookEventsConfigurations.HMAC)).put("SecretValue", secret);
        return copy;
    }
}
